class Solution:
    def unmarkedSumArray(self, nums: List[int], queries: List[List[int]]) -> List[int]:
        n = len(nums)
        marked = [False] * n
        total = sum(nums)
        ans = []
        for idx, k in queries:
            if not marked[idx]:
                marked[idx] = True
                total -= nums[idx]
            while k > 0:
                best = -1
                for i in range(n):
                    if not marked[i] and (best == -1 or nums[i] < nums[best]):
                        best = i
                if best == -1:
                    break
                marked[best] = True
                total -= nums[best]
                k -= 1
            ans.append(total)
        return ans

