class Solution {
public:
    vector<long long> unmarkedSumArray(vector<int>& nums, vector<vector<int>>& queries) {
        int n = nums.size();
        vector<bool> marked(n, false);
        long long total = accumulate(nums.begin(), nums.end(), 0LL);
        vector<long long> ans;
        for (auto& q : queries) {
            int idx = q[0], k = q[1];
            if (!marked[idx]) { marked[idx] = true; total -= nums[idx]; }
            while (k-- > 0) {
                int best = -1;
                for (int i = 0; i < n; i++)
                    if (!marked[i] && (best == -1 || nums[i] < nums[best])) best = i;
                if (best == -1) break;
                marked[best] = true;
                total -= nums[best];
            }
            ans.push_back(total);
        }
        return ans;
    }
};

