class Solution {
    public long[] unmarkedSumArray(int[] nums, int[][] queries) {
        int n = nums.length;
        Integer[] order = new Integer[n];
        for (int i = 0; i < n; i++) order[i] = i;
        Arrays.sort(order, (a, b) -> nums[a] != nums[b] ? nums[a] - nums[b] : a - b);
        boolean[] marked = new boolean[n];
        long total = 0;
        for (int x : nums) total += x;
        int p = 0;
        long[] ans = new long[queries.length];
        for (int qi = 0; qi < queries.length; qi++) {
            int idx = queries[qi][0], k = queries[qi][1];
            if (!marked[idx]) { marked[idx] = true; total -= nums[idx]; }
            while (k > 0 && p < n) {
                if (marked[order[p]]) { p++; continue; }
                marked[order[p]] = true;
                total -= nums[order[p]];
                p++;
                k--;
            }
            ans[qi] = total;
        }
        return ans;
    }
}

